  it('returns a schema rejection to the provider so a corrected retry resolves', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'lookup',
        description: 'looks things up',
        inputSchema: {
          type: 'object',
          properties: {q: {type: 'string'}},
          required: ['q'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return `found:${String(input.q)}`;
      }
    );

    let rejectionSeenByProvider = '';
    const rounds: Array<(params: SendMessageParams) => MessageChunk[]> = [
      () => [{type: 'tool_use', toolCall: {id: 'call-bad', name: 'lookup', input: {}}}, STOP_FOR_TOOL],
      params => {
        const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
        rejectionSeenByProvider = lastMessage.content[0]?.content ?? '';
        return [{type: 'tool_use', toolCall: {id: 'call-good', name: 'lookup', input: {q: 'hal'}}}, STOP_FOR_TOOL];
      },
      () => [{type: 'text', text: 'answer:found:hal'}, STOP_DONE],
    ];
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        for (const chunk of rounds[round++](params)) yield chunk;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

    const reply = await orchestrator.processMessage(createSession('find hal'));

    expect({
      reply,
      receivedInputs,
      rejectionMentionsRequiredField:
        rejectionSeenByProvider.includes('q') && /required/i.test(rejectionSeenByProvider),
    }).toEqual({
      reply: 'answer:found:hal',
      receivedInputs: [{q: 'hal'}],
      rejectionMentionsRequiredField: true,
    });
  });
});

